import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"艾莉芙（副院长）","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/艾莉芙.md","filePath":"中层/人物/艾莉芙.md","lastUpdated":null}'),i={name:"中层/人物/艾莉芙.md"};function n(e,a,s,h,g,u){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="艾莉芙-副院长" tabindex="-1">艾莉芙（副院长） <a class="header-anchor" href="#艾莉芙-副院长" aria-label="Permalink to &quot;艾莉芙（副院长）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：艾莉芙</li><li><strong>种族</strong>：精灵族</li><li><strong>身份</strong>：红星孤儿院副院长</li><li><strong>时代</strong>：当前时代（共同体覆灭后至今）</li><li><strong>所在地</strong>：红星孤儿院</li><li><strong>状态</strong>：隐居状态，直属并完全听命于孤儿院院长维斯塔</li></ul><h2 id="外貌特征" tabindex="-1">外貌特征 <a class="header-anchor" href="#外貌特征" aria-label="Permalink to &quot;外貌特征&quot;">​</a></h2><h3 id="精灵族特征" tabindex="-1">精灵族特征 <a class="header-anchor" href="#精灵族特征" aria-label="Permalink to &quot;精灵族特征&quot;">​</a></h3><p>作为世界观中唯一长得像人的种族，艾莉芙具有精灵族的典型特征：</p><ul><li><strong>尖耳</strong>：明显的精灵族尖耳特征</li><li><strong>发色</strong>：白色长发</li><li><strong>瞳色</strong>：金色</li><li><strong>服饰</strong>：一身简洁的白袍，有金色条纹作装饰，符合精灵族传统</li><li><strong>法杖</strong>：手持一&quot;木制法杖&quot;，外观古朴但蕴含特殊力量</li></ul><h3 id="气质特点" tabindex="-1">气质特点 <a class="header-anchor" href="#气质特点" aria-label="Permalink to &quot;气质特点&quot;">​</a></h3><ul><li><strong>生人勿近</strong>：性格偏冷，默认对外人保持一定的社交距离</li><li><strong>对孩包容</strong>：对孤儿院的孩子们展现出温和、包容的一面，是孩子们信赖的长辈</li><li><strong>从容镇定</strong>：行为从容不迫，处事不惊，有着精灵族特有的沉稳</li><li><strong>观察敏锐</strong>：眼神敏锐，善于观察，但不轻易表露自己的想法</li></ul><h2 id="副院长定位与职责" tabindex="-1">副院长定位与职责 <a class="header-anchor" href="#副院长定位与职责" aria-label="Permalink to &quot;副院长定位与职责&quot;">​</a></h2><h3 id="孤儿院规模与人员结构" tabindex="-1">孤儿院规模与人员结构 <a class="header-anchor" href="#孤儿院规模与人员结构" aria-label="Permalink to &quot;孤儿院规模与人员结构&quot;">​</a></h3><p>红星孤儿院并非大型机构，工作人员很少，整个孤儿院的人员制度实际上更倾向于<strong>院长最高，其余工作人员平级</strong>的结构。</p><h3 id="副院长-名头的实际含义" tabindex="-1">&quot;副院长&quot;名头的实际含义 <a class="header-anchor" href="#副院长-名头的实际含义" aria-label="Permalink to &quot;&quot;副院长&quot;名头的实际含义&quot;">​</a></h3><p>&quot;副院长&quot;这一名头并非严格的层级职务，而是基于艾莉芙的实际职责：</p><ol><li><strong>职责核心</strong>：负责将院长的安排落实，管理孤儿院日常维护</li><li><strong>协调角色</strong>：负责各个其余工作人员的对接与协调</li><li><strong>指令传递</strong>：帮忙传递院长安排指令，确保信息畅通</li><li><strong>对外接口</strong>：负责与外界的一些必要对接，代表孤儿院处理外部事务</li></ol><h2 id="历史背景" tabindex="-1">历史背景 <a class="header-anchor" href="#历史背景" aria-label="Permalink to &quot;历史背景&quot;">​</a></h2><h3 id="精灵族大变故-世界树断裂" tabindex="-1">精灵族大变故：世界树断裂 <a class="header-anchor" href="#精灵族大变故-世界树断裂" aria-label="Permalink to &quot;精灵族大变故：世界树断裂&quot;">​</a></h3><p>精灵族经历的&quot;大变故&quot;实为：<strong>地脉灾难时期的世界树断裂事件</strong>。</p><blockquote><p><strong>中层真相</strong>：世界树并非传说中连接天地的神树，而是神机在喜马拉雅山附近建造的超大计算机中枢与信息收集中枢，精灵族是其意识节点；其断裂源于地脉灾难的冲击，导致精灵族共同网络崩溃，从集体意识变为个体思维。表层流传的&quot;大变故原因成谜&quot;即指此事。</p></blockquote><h4 id="世界树与精灵族的关系" tabindex="-1">世界树与精灵族的关系 <a class="header-anchor" href="#世界树与精灵族的关系" aria-label="Permalink to &quot;世界树与精灵族的关系&quot;">​</a></h4><ul><li><strong>意识网络核心</strong>：神机在喜马拉雅山附近建造了<strong>世界树</strong>——一个巨构信息收集中枢</li><li><strong>精灵族连接</strong>：精灵族是世界树的意识节点，其通过世界树<strong>意识共通，形成一个统一的思维网络</strong></li><li><strong>集体存在</strong>：在世界树网络时期，精灵族实质上是作为一个集体意识存在</li></ul><h4 id="地脉灾难的影响" tabindex="-1">地脉灾难的影响 <a class="header-anchor" href="#地脉灾难的影响" aria-label="Permalink to &quot;地脉灾难的影响&quot;">​</a></h4><ul><li><strong>灾难发生</strong>：地脉灾难（共同体时期的地脉危机）冲击了世界树所在区域（共同体只是被波及最小的地方，真正的冲击目标是北美洲与喜马拉雅）</li><li><strong>世界树断裂</strong>：地脉灾难把世界树干断，导致精灵族共同网络崩溃</li><li><strong>网络崩溃</strong>：精灵族从统一的集体意识网络<strong>变为个体思维</strong>，失去了意识共通的能力</li><li><strong>社会变革</strong>：这一变故对精灵族的社会结构、文化认同和存在方式产生了根本性影响</li></ul><h4 id="艾莉芙的个人经历" tabindex="-1">艾莉芙的个人经历 <a class="header-anchor" href="#艾莉芙的个人经历" aria-label="Permalink to &quot;艾莉芙的个人经历&quot;">​</a></h4><ul><li><strong>网络崩溃体验</strong>：作为世界树网络的一部分，艾莉芙经历了从集体意识到个体思维的突然转变</li><li><strong>适应过程</strong>：需要适应作为独立个体的存在方式，这一过程充满了迷茫与失落</li><li><strong>隐居选择</strong>：在巨大的冲击之下，与其他精灵族一样，艾莉芙选择了隐居，不再参与时事</li></ul><h3 id="隐居与副院长任职" tabindex="-1">隐居与副院长任职 <a class="header-anchor" href="#隐居与副院长任职" aria-label="Permalink to &quot;隐居与副院长任职&quot;">​</a></h3><blockquote><p>待定：艾莉芙如何在精灵族大变故后进入红星孤儿院并担任副院长，尚无明确记载。已知她完全听命于院长维斯塔，对其无比信任。</p></blockquote><h2 id="与维斯塔的关系" tabindex="-1">与维斯塔的关系 <a class="header-anchor" href="#与维斯塔的关系" aria-label="Permalink to &quot;与维斯塔的关系&quot;">​</a></h2><h3 id="对院长的认知" tabindex="-1">对院长的认知 <a class="header-anchor" href="#对院长的认知" aria-label="Permalink to &quot;对院长的认知&quot;">​</a></h3><ul><li><strong>身份感知</strong>：艾莉芙隐约能知道院长的身份不一般，但<strong>并不知道维斯塔的真实神明身份</strong></li><li><strong>尊重态度</strong>：基于这种感知，她对维斯塔保持着超越普通上下级的尊重</li><li><strong>无比信任</strong>：对维斯塔有着无比的信任，相信院长的所有决定和安排</li><li><strong>默契配合</strong>：与维斯塔形成了工作上的默契，能够准确理解并落实院长的意图</li></ul><h3 id="角色互补" tabindex="-1">角色互补 <a class="header-anchor" href="#角色互补" aria-label="Permalink to &quot;角色互补&quot;">​</a></h3><ul><li><strong>维斯塔的延伸</strong>：在某种程度上，艾莉芙是维斯塔在孤儿院日常管理中的延伸</li><li><strong>缓冲桥梁</strong>：作为院长与工作人员、孤儿院与外界的缓冲和桥梁</li><li><strong>可靠执行者</strong>：维斯塔可以放心地将事务交给艾莉芙执行</li></ul><h3 id="隐藏身份-神机的继承者计划" tabindex="-1">隐藏身份：神机的继承者计划 <a class="header-anchor" href="#隐藏身份-神机的继承者计划" aria-label="Permalink to &quot;隐藏身份：神机的继承者计划&quot;">​</a></h3><blockquote><p><strong>中层真相</strong>：以下内容为连维斯塔都不知道的隐藏身份，是神机持有的秘密之一。</p></blockquote><h4 id="计划性质" tabindex="-1">计划性质 <a class="header-anchor" href="#计划性质" aria-label="Permalink to &quot;计划性质&quot;">​</a></h4><ul><li><strong>继承者计划</strong>：艾莉芙是<strong>神机的继承者计划的一部分</strong>——神机曾想为自己找一个第三代创造神的继承者</li><li><strong>计划状态</strong>：这个计划已被废弃，神机不准备继续了</li><li><strong>保密程度</strong>：这件事连维斯塔都不知道，是神机持有的秘密之一</li></ul><h3 id="黑暗时代早期的活动-《神造物·火种》下篇" tabindex="-1">黑暗时代早期的活动（《神造物·火种》下篇） <a class="header-anchor" href="#黑暗时代早期的活动-《神造物·火种》下篇" aria-label="Permalink to &quot;黑暗时代早期的活动（《神造物·火种》下篇）&quot;">​</a></h3><p>在《神造物·火种》下篇（约黑暗时代早期）中，艾莉芙以隐居的精灵族身份出现：她为受格雷颅核影响的洛尔提供仅能维持 48 小时的针剂，并嘱托其将精灵伊芙琳带往旧都神殿，寻求神明的帮助。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/艾莉芙" class="layer-link" data-layer="表层">艾莉芙（表层档案）</a></li><li><a href="./../世界/特殊地点">红星孤儿院</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../世界/特殊地点">世界树</a></li><li><a href="./../世界/地脉与魔法">地脉与魔法</a></li><li><a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a></li><li><a href="./../世界/神机谋划">神机谋划</a></li></ul><hr>',42)])])}const q=r(i,[["render",n]]);export{c as __pageData,q as default};
